'use strict';
let shopTab='buy',shopCategory='All',placingItem=null,shopReturn='home',shopNotice='Play the game. Earn stars. Make this shop yours!';
function shopArt(item,size=112){
  if(!item)return '';const c=item.colour||'#baa288';let body='';
  const shirt=(x,y,fill)=>`<path d="M${x} ${y}l-9 7 5 8 5-3v23h24v-23l5 3 5-8-9-7-5 4h-7z" fill="${fill}" stroke="#3d4057" stroke-width="1.4" stroke-linejoin="round"/>`;
  if(item.kind==='wall'||item.kind==='floor')body=`<rect x="19" y="16" width="82" height="78" rx="12" fill="${c}" stroke="#4e475b" stroke-width="2"/><path d="M28 82L91 26M42 91l50-48" stroke="white" stroke-opacity=".4" stroke-width="8"/><path d="M75 26l7 6 11-13" fill="none" stroke="#4e475b" stroke-width="3"/>`;
  else switch(item.art){
    case 'rack':body=`<path d="M22 94V21h76v73M14 95h16m60 0h16M20 24h80" fill="none" stroke="${c}" stroke-width="6" stroke-linecap="round"/><path d="M39 28v7l-12 8h25l-13-8M78 28v7l-12 8h25l-13-8" fill="none" stroke="#6b6270" stroke-width="2"/>${shirt(30,39,'#e8b6a1')}${shirt(69,39,'#ada5d7')}`;break;
    case 'till':body=`<path d="M15 58h90v37H15z" fill="${c}" stroke="#4b4357" stroke-width="2"/><path d="M12 52h96v10H12z" fill="#dfbf98" stroke="#4b4357" stroke-width="2"/><rect x="38" y="23" width="43" height="28" rx="4" fill="#3a4258"/><rect x="43" y="28" width="33" height="16" rx="2" fill="#bde1cb"/><path d="M55 51v-8M67 51v-8" stroke="#3a4258" stroke-width="4"/><rect x="25" y="69" width="25" height="5" rx="2" fill="#ffffff70"/><path d="M63 78h27" stroke="#4b4357" stroke-width="2"/>`;break;
    case 'plant':body=`<path d="M60 73V26M60 49L41 34M60 62l20-18" fill="none" stroke="#547b56" stroke-width="3"/><ellipse cx="41" cy="32" rx="11" ry="20" transform="rotate(-42 41 32)" fill="${c}"/><ellipse cx="77" cy="43" rx="11" ry="20" transform="rotate(40 77 43)" fill="#86b18a"/><ellipse cx="59" cy="23" rx="9" ry="17" fill="#507e5c"/><path d="M37 68h46l-8 32H45z" fill="#e6b295" stroke="#7d605a" stroke-width="2"/><path d="M35 67h50v9H35z" fill="#efc4a5"/>`;break;
    case 'star':body=`<path d="M60 19l10 21 24 4-17 18 3 25-20-12-21 12 4-25-18-18 25-4z" fill="${c}" stroke="#826843" stroke-width="2"/><path d="M60 83v17m-15 0h30" stroke="#826843" stroke-width="5" stroke-linecap="round"/>`;break;
    case 'rug':body=`<ellipse cx="60" cy="79" rx="48" ry="21" fill="${c}" stroke="#ad7d71" stroke-width="2"/><ellipse cx="60" cy="79" rx="38" ry="15" fill="none" stroke="#f7e2d0" stroke-width="2"/><path d="M60 68l5 7 12 1-8 5 2 8-11-4-10 4 2-8-8-5 11-1z" fill="#fff0d6"/>`;break;
    case 'sale':body=`<path d="M30 30h60l8 67H21z" fill="${c}" stroke="#8d6259" stroke-width="3"/><rect x="33" y="41" width="53" height="39" rx="3" fill="#fff9e9"/><text x="60" y="66" text-anchor="middle" fill="#c65d47" font-family="sans-serif" font-size="18" font-weight="bold">SALE</text><path d="M24 99l-5 4m78-4 4 4" stroke="#8d6259" stroke-width="3"/>`;break;
    case 'table':body=`<path d="M22 64v35m76-35v35" stroke="#b08a68" stroke-width="8"/><path d="M13 55h94v15H13z" fill="#dfbf98" stroke="#9b7a5c" stroke-width="2"/><path d="M26 43h35v12H26z" fill="#b1a5d3" stroke="#797287"/><path d="M29 35h35v9H29z" fill="#d4bedb" stroke="#797287"/><path d="M69 44h25v11H69z" fill="${c}" stroke="#6b8064"/><path d="M66 37h25v8H66z" fill="#c9d6a8" stroke="#6b8064"/>`;break;
    case 'shoes':body=`<rect x="18" y="24" width="84" height="77" rx="3" fill="${c}" stroke="#786658" stroke-width="2"/><path d="M23 55h74m-74 35h74" stroke="#eee0c9" stroke-width="5"/><path d="M30 34v13h24c4-9-8-7-13-14zM65 34v13h24c4-9-8-7-13-14z" fill="#eee1d0" stroke="#7d7781" stroke-width="1.5"/><path d="M30 67v13h24c4-9-8-7-13-14zM65 67v13h24c4-9-8-7-13-14z" fill="#a4bbaf" stroke="#6c7c79" stroke-width="1.5"/>`;break;
    case 'bags':body=`<path d="M60 20v78m-22 0h44M25 35h70" stroke="#8c6e71" stroke-width="5" stroke-linecap="round"/><path d="M19 48h29v33H19z" fill="${c}" stroke="#7b5e72" stroke-width="2"/><path d="M25 48V40a8 8 0 0117 0v8" fill="none" stroke="#7b5e72" stroke-width="2"/><path d="M73 48h29v33H73z" fill="#e2b58e" stroke="#97775e" stroke-width="2"/><path d="M79 48V40a8 8 0 0117 0v8" fill="none" stroke="#97775e" stroke-width="2"/>`;break;
    case 'mirror':body=`<path d="M33 96V36a27 27 0 0154 0v60z" fill="#dbe9e9" stroke="${c}" stroke-width="7"/><path d="M40 65l37-29M43 83l35-27" stroke="#ffffffbb" stroke-width="7"/><path d="M29 101h62" stroke="#947e64" stroke-width="5" stroke-linecap="round"/>`;break;
    case 'chair':body=`<path d="M32 63V37c0-23 56-23 56 0v26" fill="${c}" stroke="#54796f" stroke-width="2"/><rect x="23" y="58" width="74" height="31" rx="9" fill="${c}" stroke="#54796f" stroke-width="2"/><rect x="20" y="49" width="13" height="34" rx="6" fill="#a2c0b3"/><rect x="87" y="49" width="13" height="34" rx="6" fill="#a2c0b3"/><path d="M32 89v12m56-12v12" stroke="#95755b" stroke-width="5"/>`;break;
    case 'display':body=`<path d="M15 93h90v10H15z" fill="${c}" stroke="#89724c" stroke-width="2"/><path d="M60 76v17m-11-1h22" stroke="#817264" stroke-width="4"/><path d="M53 20h14l-2 11 12 7-4 37H47l-4-37 12-7z" fill="#ead9c1" stroke="#a48e78" stroke-width="2"/><path d="M45 36l-11 8 8 13 7-4-3 24h28l-3-24 7 4 8-13-11-8-10 4H55z" fill="#aca2cd" stroke="#70658e" stroke-width="2"/><path d="M60 10l3 5 6 1-4 4 1 6-6-3-6 3 1-6-4-4 6-1z" fill="#e8b954"/>`;break;
  }
  return `<svg viewBox="0 0 120 112" width="${size}" height="${size}" aria-hidden="true" focusable="false"><ellipse cx="60" cy="102" rx="45" ry="6" fill="#44354d12"/>${body}</svg>`;
}
function updateWalletUI(){const saved=starShop.snapshot();const count=$('#wallet-count');if(count)count.textContent=saved.balance;$('#my-shop')?.setAttribute('aria-label',`My shop. ${saved.balance} saved stars`)}
function earnShopStars(id,amount){const added=starShop.credit(id,amount);updateWalletUI();return added}
function openShop(){
  if(spinning){say('The wheel is spinning. Your shop will be ready in a moment.');return}
  if(screen!=='shop'){shopReturn=screen;if(screen==='question')numberDraft=$('#number-answer')?.value||''}
  stopSpeech();screen='shop';showShop();goTop();
}
function closeShop(){placingItem=null;stopSpeech();const back=shopReturn;screen=back;if(back==='question'&&state)renderQuestion();else if(back==='wheel'&&state)showWheel();else if(back==='finish'&&state)finish();else home();goTop()}
function roomHTML(saved){return `<div class="room-scene ${placingItem?'is-placing':''}" data-wall="${saved.wall}" data-floor="${saved.floor}"><div class="room-wall"></div><div class="room-floor"></div><div class="room-window" aria-hidden="true"><i></i><i></i></div><div class="room-lamp lamp-left" aria-hidden="true"></div><div class="room-lamp lamp-right" aria-hidden="true"></div><div class="room-name">${text(saved.name)} <span aria-hidden="true">✦</span></div><div class="room-skirt" aria-hidden="true"></div><div class="room-spots">${SHOP_SPOTS.map((name,i)=>{const item=SHOP_ITEM_MAP[saved.placements[i]];return `<button class="room-spot ${item?'has-item':'empty-spot'} ${i<3?'back-spot':'front-spot'}" data-spot="${i}" aria-label="${name}: ${item?item.name:'empty'}. ${placingItem?'Place '+SHOP_ITEM_MAP[placingItem].name+' here':item?'Move or put away':'Choose an item first'}"><span class="spot-art">${item?shopArt(item,125):'<span class="spot-plus">+</span>'}</span><span class="spot-name">${name}</span></button>`}).join('')}</div><div class="room-door-mat" aria-hidden="true">WELCOME</div></div>`}
function showShop(){
  screen='shop';const saved=starShop.snapshot();updateWalletUI();const categories=['All','Furniture','Clothes','Decor','Colours'];const items=SHOP_ITEMS.filter(item=>(shopTab==='owned'?saved.owned.includes(item.id):item.price>0)&&(shopCategory==='All'||shopCategory===item.category));
  app.innerHTML=`<div class="shop-heading"><div><div class="eyebrow">Your stars. Your style.</div><h1>My Star Shop</h1><p>Earn stars. Buy items. Make it yours.</p></div><button class="secondary" id="shop-back">← ${shopReturn==='home'?'Back to game':shopReturn==='finish'?'Back to my stars':'Back to my show'}</button></div><div class="shop-layout"><section class="shop-room-card" aria-label="Your decorated shop"><div class="room-toolbar"><span><span aria-hidden="true">🏪</span> ${text(saved.name)}</span><div class="room-toolbar-actions"><button class="shop-read" id="read-shop">◖♪ Read to me</button><button class="small-action" id="rename-shop">Change name ✎</button></div></div>${roomHTML(saved)}<div class="room-instruction ${placingItem?'placing':''}" role="status">${placingItem?`<span>${shopArt(SHOP_ITEM_MAP[placingItem],42)}</span><span><strong>Place your ${text(SHOP_ITEM_MAP[placingItem].name.toLowerCase())}.</strong><br>Tap one of the six spots.</span><button class="small-action" id="cancel-place">Cancel</button>`:'<span aria-hidden="true">☝</span><span>Tap an item in your shop to move it or put it away.</span>'}</div></section><aside class="shop-wallet"><div class="wallet-label">MY SAVED STARS</div><div class="wallet-number"><span aria-hidden="true">★</span> ${saved.balance}</div><p>Spend some.<br>Save some for later.</p><button class="primary" id="earn-more">Earn more stars ↗</button><div class="wallet-note" id="shop-notice" role="status">${text(shopNotice)}</div><div class="saving-note"><span aria-hidden="true">${starShop.persistent?'✓':'ⓘ'}</span> ${starShop.persistent?'Saved in this browser.':'Saving is unavailable. This visit only.'}<br><span>Use this browser to visit your shop again.</span></div></aside></div><section class="shop-market" aria-labelledby="market-title"><div class="market-heading"><div><h2 id="market-title">${shopTab==='buy'?'A little something for your shop':'Your collection'}</h2><p>${shopTab==='buy'?'Pick an item. Check the price. Make it yours.':'You own these items. Use them as often as you like.'}</p></div><div class="shop-tabs" aria-label="Item list"><button id="buy-tab" aria-pressed="${shopTab==='buy'}">Buy items</button><button id="owned-tab" aria-pressed="${shopTab==='owned'}">My items <span>${saved.owned.length}</span></button></div></div><div class="shop-categories" aria-label="Item categories">${categories.map(c=>`<button data-category="${c}" aria-pressed="${shopCategory===c}">${c}</button>`).join('')}</div>${shopTab==='owned'&&shopCategory==='Colours'?`<div class="basic-colours"><span>Free colours:</span><button id="basic-wall" class="small-action">Cream walls</button><button id="basic-floor" class="small-action">Wood floor</button></div>`:''}<div class="shop-item-grid">${items.length?items.map(item=>{const owned=saved.owned.includes(item.id),placed=saved.placements.includes(item.id),used=item.kind!=='item'&&saved[item.kind]===item.value;return `<article class="shop-item-card ${placingItem===item.id?'chosen':''}"><div class="item-art" style="--item-colour:${item.colour}">${shopArt(item,112)}${owned?'<span class="owned-tick">✓ Yours</span>':''}</div><div class="item-card-info"><span class="item-kind">${item.kind==='wall'?'Wall colour':item.kind==='floor'?'Floor colour':item.category}</span><h3>${text(item.name)}</h3><div class="item-card-bottom"><span class="item-cost">${item.price===0?'Free':`★ ${item.price}`}</span><button class="${owned?'use-button':'buy-button'}" data-item="${item.id}" ${used?'disabled':''} aria-label="${owned?(used?'Using ':placed?'Move ':'Use '):'Buy '}${text(item.name)}${owned?'':' for '+item.price+(item.price===1?' star':' stars')}">${owned?(used?'Using ✓':placed?'Move':'Use item'):saved.balance>=item.price?'Buy':'Save '+(item.price-saved.balance)+' more'}</button></div></div></article>`}).join(''):'<p class="empty">No items here yet. Earn stars and choose something you like.</p>'}</div></section>`;
  bind('read-shop',()=>read('Welcome to your shop. You have '+starShop.snapshot().balance+' saved stars. Choose an item. Check the price. Tap Buy. Then tap a spot in your shop to place it. You can save your stars for later.'));bind('shop-back',closeShop);bind('earn-more',()=>{shopReturn==='question'||shopReturn==='wheel'?closeShop():home();goTop()});bind('rename-shop',renameShop);bind('cancel-place',()=>{placingItem=null;showShop()});bind('buy-tab',()=>{shopTab='buy';shopCategory='All';showShop()});bind('owned-tab',()=>{shopTab='owned';shopCategory='All';showShop()});bind('basic-wall',()=>{starShop.theme('wall','cream');showShop()});bind('basic-floor',()=>{starShop.theme('floor','oak');showShop()});document.querySelectorAll('[data-category]').forEach(button=>button.onclick=()=>{shopCategory=button.dataset.category;showShop()});document.querySelectorAll('[data-item]').forEach(button=>button.onclick=()=>chooseShopItem(button.dataset.item));document.querySelectorAll('[data-spot]').forEach(button=>button.onclick=()=>tapShopSpot(Number(button.dataset.spot)));
}
function chooseShopItem(id){const item=SHOP_ITEM_MAP[id];if(!item)return;const saved=starShop.snapshot();if(saved.owned.includes(id)){if(item.kind==='item'){placingItem=id;shopNotice='Tap a spot to place your '+item.name.toLowerCase()+'.';showShop();$('.room-instruction')?.scrollIntoView({behavior:'smooth',block:'center'});document.querySelector('[data-spot="0"]')?.focus({preventScroll:true});say(shopNotice)}else{placingItem=null;starShop.theme(item.kind,item.value);shopNotice='Now using '+item.name.toLowerCase()+'.';showShop();say(shopNotice)}return}
  if(saved.balance<item.price){const need=item.price-saved.balance;openDialog(`<h2>Keep saving!</h2><div class="purchase-art">${shopArt(item,120)}</div><p>A ${text(item.name.toLowerCase())} costs <strong>${item.price} stars</strong>.</p><p>You have <strong>${saved.balance} stars</strong>.<br>Save <strong>${need} more ${need===1?'star':'stars'}</strong> to buy it.</p><button class="primary" id="keep-saving">Keep saving ★</button>`);bind('keep-saving',()=>$('#dialog').close());return}
  openDialog(`<h2>Buy ${text(item.name.toLowerCase())}?</h2><div class="purchase-art">${shopArt(item,120)}</div><div class="purchase-maths"><div><span>You have</span><strong>★ ${saved.balance}</strong></div><span aria-hidden="true">−</span><div><span>Cost</span><strong>★ ${item.price}</strong></div><span aria-hidden="true">=</span><div><span>Stars left</span><strong>★ ${saved.balance-item.price}</strong></div></div><div class="purchase-actions"><button class="primary" id="confirm-buy">Buy for ${item.price} ${item.price===1?'star':'stars'}</button><button class="secondary" id="not-now">Not now</button></div>`);bind('not-now',()=>$('#dialog').close());bind('confirm-buy',()=>purchaseShopItem(id));
}
function purchaseShopItem(id){const result=starShop.buy(id);$('#dialog').close();if(!result.ok){shopNotice=result.reason==='owned'?'You already own this item. Use it from My items.':'You need more stars for this item.';showShop();say(shopNotice);return}initAudio();sfx(true);placingItem=result.item.kind==='item'?id:null;shopNotice=`${result.before} − ${result.cost} = ${result.left}. You bought ${result.item.name.toLowerCase()}! ${placingItem?'Tap a spot to place it.':''}`;showShop();say(shopNotice);$('.shop-room-card')?.scrollIntoView({behavior:'smooth',block:'start'});if(placingItem)document.querySelector('[data-spot="0"]')?.focus({preventScroll:true})}
function tapShopSpot(spot){const saved=starShop.snapshot();if(placingItem){const id=placingItem,replaced=saved.placements[spot];if(starShop.place(id,spot)){placingItem=null;shopNotice=`Your ${SHOP_ITEM_MAP[id].name.toLowerCase()} is in your shop!${replaced&&replaced!==id?' The other item is in My items.':''}`;showShop();say(shopNotice);document.querySelector(`[data-spot="${spot}"]`)?.focus({preventScroll:true})}return}const id=saved.placements[spot];if(!id){shopNotice='Pick an item from My items. Then tap this spot.';showShop();say(shopNotice);return}const item=SHOP_ITEM_MAP[id];openDialog(`<h2>${text(item.name)}</h2><div class="purchase-art">${shopArt(item,120)}</div><p>Move it to another spot, or put it back in My items.<br>You keep the item. This costs no stars.</p><div class="purchase-actions"><button class="primary" id="move-item">Move item ↗</button><button class="secondary" id="put-away">Put away</button></div>`);bind('move-item',()=>{$('#dialog').close();chooseShopItem(id)});bind('put-away',()=>{$('#dialog').close();starShop.remove(spot);shopNotice='Your '+item.name.toLowerCase()+' is in My items. You can use it again.';showShop();say(shopNotice)})}
function renameShop(){const saved=starShop.snapshot();openDialog(`<h2>Name your shop</h2><label class="shop-name-label" for="shop-name-input">Shop name</label><input class="shop-name-input" id="shop-name-input" maxlength="24" value="${text(saved.name)}" autocomplete="off"><p class="micro">Use up to 24 characters.</p><button class="primary" id="save-shop-name">Save name ✓</button>`);bind('save-shop-name',()=>{if(!starShop.rename($('#shop-name-input').value)){say('Type a name for your shop.');return}$('#dialog').close();showShop();say('Shop name saved.')})}
const IPAD_GAME_URL='https://retail-showtime-classroom-7k4.abubakarhasyim18.chatgpt.site';
function shareIPads(){openDialog(`<h2>Open on an iPad</h2><div class="ipad-link"><img class="ipad-qr" src="ipad-qr.png" width="200" height="200" alt="QR code for the Retail Showtime game"><div><p><strong>Scan with the iPad camera.</strong><br>Tap the link that appears.<br>No sign-in is needed.</p><a href="${IPAD_GAME_URL}" target="_blank" rel="noopener">Open the game ↗</a></div></div><label class="micro" for="ipad-url">Student game link</label><input id="ipad-url" class="ipad-url" readonly value="${IPAD_GAME_URL}"><div class="ipad-dialog-actions"><button class="primary" id="copy-ipad-link">Copy game link</button><a href="ipad-qr.png" download="Retail-Showtime-iPad-QR.png">Save QR code ↓</a></div><p class="ipad-status" id="ipad-copy-status" role="status"></p><h3>Add to the Home Screen</h3><ol class="ipad-steps"><li>Open the game in <strong>Safari</strong>.</li><li>Tap <strong>Share</strong>.</li><li>Tap <strong>Add to Home Screen</strong>, then <strong>Add</strong>.</li></ol><p class="micro">Use the same browser or Home Screen shortcut each time. Stars and decorations save on that iPad. Different devices have separate shops. An internet connection is needed to load the game.</p>`);bind('copy-ipad-link',async()=>{try{await navigator.clipboard.writeText(IPAD_GAME_URL);$('#ipad-copy-status').textContent='Link copied. Paste it into your class app or message.'}catch{$('#ipad-url').focus();$('#ipad-url').select();$('#ipad-copy-status').textContent='Touch and hold the selected link. Then tap Copy.'}})}
